import{_ as n,a0 as p,w as g,s,I as a,x as o,a1 as l,A as r,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux 系统中使用 logwatch 监控日志文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系统中使用 logwatch 监控日志文件 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系统中使用 logwatch 监控日志文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系统中使用 logwatch 监控日志文件 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141021 How to monitor a log file on Linux with logwatch","title":"Linux 系统中使用 logwatch 监控日志文件","tag":"201412","desc":""},"relativePath":"201412/20141021 How to monitor a log file on Linux with logwatch.md","filePath":"[post].md"}'),c={name:"201412/20141021 How to monitor a log file on Linux with logwatch.md"};function d(h,t,u,w,m,f){const e=p("Link");return g(),s("div",null,[t[18]||(t[18]=a("h1",{id:"linux-系统中使用-logwatch-监控日志文件",tabindex:"-1"},[o("Linux 系统中使用 logwatch 监控日志文件 "),a("a",{class:"header-anchor",href:"#linux-系统中使用-logwatch-监控日志文件","aria-label":"Permalink to “Linux 系统中使用 logwatch 监控日志文件”"},"​")],-1)),t[19]||(t[19]=a("p",null,"Linux 操作系统和许多应用程序会创建特殊的文件来记录它们的运行事件，这些文件通常被称作“日志”。当要了解操作系统或第三方应用程序的行为或进行故障排查时，这些系统日志或特定的应用程序日志文件是必不可少的的工具。但是，日志文件并没有您们所谓的“清晰”或“容易”这种程度的可读性。手工分析原始的日志文件简直是浪费时间，并且单调乏味。出于这个原因，对于系统管理员来说，发现任何一款能把原始的日志文件转换成更人性化的记录摘要的工具，将会受益无穷。",-1)),a("p",null,[l(e,{href:"http://sourceforge.net/projects/logwatch/"},{default:r(()=>[...t[0]||(t[0]=[o("logwatch",-1)])]),_:1}),t[1]||(t[1]=o(" 是一款用 Perl 语言编写的开源日志解析分析器。它能对原始的日志文件进行解析并转换成结构化格式的文档，也能根据您的使用情况和需求来定制报告。logwatch 的主要目的是生成更易于使用的日志摘要，并不是用来对日志进行实时的处理和监控的。正因为如此，logwatch 通常被设定好时间和频率的自动定时任务来调度运行或者是有需要日志处理的时候从命令行里手动运行。一旦日志报告生成，logwatch 可以通过电子邮件把这报告发送给您，您可以把它保存成文件或者直接显示在屏幕上。",-1))]),t[20]||(t[20]=i(`<p>Logwatch 报告的详细程度和报告覆盖范围是完全可定制化的。Logwatch 的日志处理引擎也是可扩展的，从某种意义上来说，如果您想在一个新的应用程序中使用 logwatch 功能的话，只需要为这个应用程序的日志文件编写一个日志处理脚本（使用 Perl 语言），然后挂接到 logwatch 上就行。</p><p>logwatch 有一点不好的就是，在它生成的报告中没有详细的时间戳信息，而原来的日志文件中是存在的。您只能知道被记录下来的一段时间之内的特定事件，如果想要知道精确的时间点的信息，就不得不去查看原日志文件了。</p><h3 id="安装-logwatch" tabindex="-1">安装 Logwatch <a class="header-anchor" href="#安装-logwatch" aria-label="Permalink to “安装 Logwatch”">​</a></h3><p>在 Debian 系统或其派生的系统上:</p><pre><code># aptitude install logwatch 
</code></pre><p>在基于 Red Hat 的发布系统上:</p><pre><code># yum install logwatch 
</code></pre><h3 id="配置-logwatch" tabindex="-1">配置 Logwatch <a class="header-anchor" href="#配置-logwatch" aria-label="Permalink to “配置 Logwatch”">​</a></h3><p>安装时，主要的配置文件（logwatch.conf）被放到 <strong>/etc/logwatch/conf</strong> 目录中。此文件（默认是空的）定义的设置选项会覆盖掉定义在 /usr/share/logwatch/default.conf/logwatch.conf 文件中的系统级设置。</p><p>在命令行中，启动 logwatch, 如果不带参数的话，将会使用 /etc/logwatch/conf/logwatch.conf 文件中定义的选项。但，只要一指定参数，它们就会覆盖 /etc/logwatch/conf/logwatch.conf 文件中的任意默认/自定义设置。</p><p>这篇文章里，我们会编辑 /etc/logwatch/conf/logwatch.conf 文件来对一些默认的设置项做些个性化设置。</p><pre><code>Detail = &lt;Low, Med, High, 或数字&gt;
</code></pre><p>“Detail” 配置指令控制着 logwatch 报告的详细程度。它可以是个正整数，也可以是分别代表着10、5和0数字的 High、Med、Low 几个选项。</p><pre><code>MailTo = youremailaddress@yourdomain.com
</code></pre><p>如果您让把一份 logwatch 的报告邮件给您，就要使用 “MailTo” 这个配置指令。要把一份报告发送给多个用户，只需要把他们的邮件地址用空格格开，然后配置上去。但是，您需要在 logwatch 运行的服务器上配置好本地邮件传输代理（MTA）如，sendmail、 Postfix 等，这个配置指令项才能起作用。</p><pre><code>Range = &lt;Yesterday|Today|All&gt;
</code></pre><p>&quot;Range&quot; 配置指令定义了生成 logwatch 报告的时间段信息。这个指令通常可选的值是 Yesterday、Today、All。当作用了“Rang = All”时，“Archive = yes” 这个指令项也必须配置上，那么所有的已存档的日志文件 (比如，/var/log/maillog、/var/log/maillog.X 或 /var/log/maillog.X.gz 文件)都会被处理到。</p><p>除了这些通用的 range 值，您也可以使用复杂点的选择值，如下所示：</p><ul><li>Range = &quot;2 hours ago for that hour&quot;</li><li>Range = &quot;-5 days&quot;</li><li>Range = &quot;between -7 days and -3 days&quot;</li><li>Range = &quot;since September 15, 2014&quot;</li><li>Range = &quot;first Friday in October&quot;</li><li>Range = &quot;2014/10/15 12:50:15 for that second&quot;</li></ul>`,19)),a("p",null,[t[3]||(t[3]=o("要使用上面例子中自由形式的 range，您需要从 CPAN（注：Comprehensive　Perl　Archive　Network） 上下载安装 Perl 的 Date::Manip 模块。关于 CPAN 模块的安装说明，请请参阅",-1)),l(e,{href:"http://xmodulo.com/how-to-install-perl-modules-from-cpan.html"},{default:r(()=>[...t[2]||(t[2]=[o("此帖",-1)])]),_:1}),t[4]||(t[4]=o(" 。",-1))]),t[21]||(t[21]=i(`<pre><code>Service = &lt;service-name-1&gt;
Service = &lt;service-name-2&gt;
. . .
</code></pre><p>“Service” 选项指定想要监控的一个或多个服务。在 /usr/share/logwatch/scripts/services 目录下列出的服务都能被监控，它们已经涵盖了重要的系统服务（例如：pam,secure,iptables,syslogd 等），也涵盖了一些像 sudo、sshd、http、fail2ban、samba等主流的应用服务。如果您想添加新的服务到列表中，得编写一个相应的日志处理 Perl 脚本，并把它放在这个目录中。</p><p>如果这个选项要用来选择特定的服务话，您需要把 /usr/share/logwatch/default.conf/logwatch.conf 文件中的 &quot;Service = All &quot; 这一行注释掉。</p><p><img src="https://farm6.staticflickr.com/5612/14948933564_94cbc5353c_z.jpg" alt=""></p><pre><code>Format = &lt;text|html&gt;
</code></pre><p>“Format” 配置指令定义了一份 logwatch 报告的格式（比如 text 或者 HTML）。</p><pre><code>Output = &lt;file|mail|stdout&gt;
</code></pre><p>&quot;Output&quot; 配置指令定义生成的 logwatch 报告要发送的目的地。它能被保存成文件（file），生成电子邮件（mail）或者是直接在屏幕上显示（stdout）。</p><h3 id="用-logwatch-来分析日志文件" tabindex="-1">用 Logwatch 来分析日志文件 <a class="header-anchor" href="#用-logwatch-来分析日志文件" aria-label="Permalink to “用 Logwatch 来分析日志文件”">​</a></h3><p>要弄明白怎么使用 logwatch 来分析日志文件，可以参考下面的 logwatch.conf 文件例子:</p><pre><code>Detail = High
MailTo = youremailaddress@yourdomain.com
Range = Today
Service = http
Service = postfix
Service = zz-disk_space
Format = html
Output = mail
</code></pre><p>使用这些设置，logwatch 将会处理三个应用服务（http、postfix 和 zz-disk_space）当天产生的日志，生成一份非常详细的 HTML 格式报告，然后邮件给您。</p><p>如果您不想个性化 /etc/logwatch/conf/logwatch.conf，您可以不修改此文件让其默认，然后在命令行里运行如下所示的命令。也会得到同样的输出。</p><pre><code># logwatch --detail 10 --mailto youremailaddress@yourdomain.com --range today --service http --service postfix --service zz-disk_space --format html --output mail 
</code></pre><p>电子邮件发送的报告样子如图示:</p><p><img src="https://farm6.staticflickr.com/5611/15383540608_57dc37e3d6_z.jpg" alt=""></p><p>这份电子邮件头部包含指向导航到报告细节的链接，在每个选中的服务细节，也会有“返回顶部”的链接。</p><p>接收人很少的情况下您可能会使用电子邮件发送报告这个选项。其它情况下，您可能会把让其生成为 HTML 格式的报告，这样每个想看这份报告的人都可以从网络共享里看到。只需要把上面例子中的配置做些修改就可以实现:</p><pre><code>Detail = High
Range = Today
Service = http
Service = postfix
Service = zz-disk_space
Format = html
Output = file
Filename = /var/www/html/logs/dev1.html
</code></pre><p>同样的，也可以在命令行中运行如下的命令。</p><pre><code># logwatch --detail 10 --range today --service http --service postfix --service zz-disk_space --format html --output file --filename /var/www/html/logs/dev1.html 
</code></pre><p>最后，让我们使用 cron 来配置 logwatch 的定时执行任务。下面的例子中，将会在每个工作日的下午 12：15 分运行 logwatch 调度任务。</p><pre><code># crontab -e 
</code></pre><hr><pre><code>15 12 * * 1,2,3,4,5 /sbin/logwatch
</code></pre><p>希望这会有所帮助。欢迎到社区发表评论或分享自己的心得和体会！</p><hr>`,27)),a("p",null,[t[6]||(t[6]=o("via: ",-1)),l(e,{href:"http://xmodulo.com/monitor-log-file-linux-logwatch.html"},{default:r(()=>[...t[5]||(t[5]=[o("http://xmodulo.com/monitor-log-file-linux-logwatch.html",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=o("作者：",-1)),l(e,{href:"http://xmodulo.com/author/gabriel"},{default:r(()=>[...t[7]||(t[7]=[o("Gabriel Cánepa",-1)])]),_:1}),t[11]||(t[11]=o(" 译者：",-1)),l(e,{href:"https://github.com/runningwater"},{default:r(()=>[...t[8]||(t[8]=[o("runningwater",-1)])]),_:1}),t[12]||(t[12]=o(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[9]||(t[9]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=o("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原创翻译，",-1)),l(e,{href:"http://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[o("Linux中国",-1)])]),_:1}),t[17]||(t[17]=o(" 荣誉推出",-1))])])}const v=n(c,[["render",d]]);export{L as __pageData,v as default};
